  <div class="qnw-workspace">
   <section class="qnw-list-panel" :aria-label="nt('功能导航')"><div class="qnw-list-heading"><label class="qnw-search"><ClientIcon name="search"/><input v-model="query" type="search" :aria-label="nt('搜索入口或用途')" :placeholder="nt('搜索入口或用途')"/></label><button type="button" class="qnw-icon-button" :disabled="loading||busy" :aria-label="nt('重新读取')" @click="refresh"><ClientIcon name="refresh"/></button></div><div v-if="loading&&!rows.length" class="qnw-loading"><BrandLoader :size="45" :text="nt('正在读取导航')"/></div><div v-if="loadError" class="qnw-inline-error" role="alert">{{nt(loadError)}}<button type="button" class="qnw-button" :disabled="loading||busy" @click="refresh">{{nt('重新读取')}}</button></div><div v-if="!loading&&!outline.length" class="qnw-empty"><ClientIcon :name="scope==='trash'?'folder':'search'"/><b>{{nt(scope==='trash'?'还没有回收的入口':'没有匹配的入口')}}</b><p v-if="scope==='trash'">{{nt('这里保留收起的分组和入口，可以恢复。')}}</p></div>
    <div class="qnw-entry-list"><article v-for="row in outline" :key="row.id" :class="{selected:selected===row.id,dirty:dirty(row.id),conflicted:conflicts[row.id]}" :data-entry="row.id" :style="{'--qnw-depth':Math.min(row.depth,3)}" :draggable="!locked&&!row.deletedAt" @dragstart="dragged=row.id;$event.dataTransfer?.setData('text/plain',row.id)" @dragend="dragged=''" @dragover.prevent @drop.prevent="drop(row.id)"><button type="button" class="qnw-entry-pick" @click="choose(row.id)"><MenuIcon :row="row" :active="selected===row.id"/><span><b>{{menuLabel(row,currentLang)||nt('待添加')}}</b><small>{{nt(kinds[row.kind]||'站内页面')}} <template v-if="dirty(row.id)">· {{nt(bases[row.id]?'本次已改动':'本次新增')}}</template></small></span><ClientIcon v-if="conflicts[row.id]" name="info"/></button><div v-if="!row.deletedAt" class="qnw-entry-tools"><button type="button" class="qnw-icon-button" :disabled="locked" :aria-label="nt('上移')+' '+menuLabel(row,currentLang)" @click="move(row.id,-1)"><ClientIcon name="chevronUp"/></button><button type="button" class="qnw-icon-button" :disabled="locked" :aria-label="nt('下移')+' '+menuLabel(row,currentLang)" @click="move(row.id,1)"><ClientIcon name="chevronDown"/></button><label class="qnw-mini-switch"><input v-model="drafts[row.id].visible" type="checkbox" role="switch" :aria-label="nt('显示')+' '+menuLabel(row,currentLang)" :disabled="locked"/><span aria-hidden="true"></span></label></div></article></div>
   </section>
   <section v-if="currentRow" class="qnw-editor" :aria-label="nt('基本信息')"><header><div><p class="qnw-eyebrow">MAKE IT YOURS</p><h2>{{menuLabel(currentRow,currentLang)||nt('待添加')}}</h2></div><MenuIcon :row="currentRow" :active="true"/></header>
    <section v-if="conflicts[selected]" class="qnw-conflict" role="status"><b>{{nt('这项导航已有变化')}}</b><dl><div><dt>{{nt('最新内容')}}</dt><dd>{{conflicts[selected].missing?nt('入口暂时不可用'):menuLabel(conflicts[selected],currentLang)}}</dd></div><div><dt>{{nt('你的修改')}}</dt><dd>{{menuLabel(currentRow,currentLang)}}</dd></div></dl><div><button type="button" class="qnw-button" :disabled="locked" @click="resolve(selected,'latest')">{{nt('采用最新内容')}}</button><button v-if="!conflicts[selected].missing&&!conflicts[selected].deletedAt" type="button" class="qnw-button" :disabled="locked" @click="resolve(selected,'mine')">{{nt('保留我的修改，重新核对')}}</button></div></section>
    <template v-if="currentRow.deletedAt"><p class="qnw-editor-note">{{nt('这里保留收起的分组和入口，可以恢复。')}}</p><button type="button" class="qnw-button qnw-primary" :disabled="locked||!!changes.length" @click="organize(selected,'restore')"><ClientIcon name="refresh"/>{{nt(currentRow.kind==='group'?'恢复这组入口':'恢复这个入口')}}</button></template>
    <div v-else class="qnw-form">
     <label class="qnw-label">{{nt('导航名称')}}<input v-model="drafts[selected].title" :aria-label="nt('导航名称')" maxlength="80" :disabled="locked"/></label><div class="qnw-name-tools"><button v-if="currentRow.kind==='internal'" type="button" :disabled="locked" @click="useDefaultName">{{nt('使用默认名称')}}</button><button v-if="drafts[selected].standardKey" type="button" :disabled="locked" @click="drafts[selected].standardKey=''">{{nt('自定义名称')}}</button></div>
     <div class="qnw-two"><label class="qnw-label">{{nt('英文名称')}}<input v-model="drafts[selected].titleEn" :aria-label="nt('英文名称')" maxlength="80" :placeholder="currentRow.standardKey?menuLabel({...currentRow,titleEn:''},'en'):currentRow.title" :disabled="locked"/></label><label class="qnw-label">{{nt('繁体名称')}}<input v-model="drafts[selected].titleTw" :aria-label="nt('繁体名称')" maxlength="80" :placeholder="currentRow.standardKey?menuLabel({...currentRow,titleTw:''},'zh-TW'):currentRow.title" :disabled="locked"/></label></div><p class="qnw-field-note">{{nt('留空时沿用默认名称或原名称。')}}</p>
     <label class="qnw-label">{{nt('入口提示')}}<textarea v-model="drafts[selected].hint" :aria-label="nt('入口提示')" maxlength="500" rows="2" :disabled="locked"></textarea></label><details class="qnw-extra-language"><summary>{{nt('英文提示')}} / {{nt('繁体提示')}}</summary><div class="qnw-two"><label class="qnw-label">{{nt('英文提示')}}<textarea v-model="drafts[selected].hintEn" maxlength="500" rows="2" :aria-label="nt('英文提示')" :disabled="locked"></textarea></label><label class="qnw-label">{{nt('繁体提示')}}<textarea v-model="drafts[selected].hintTw" maxlength="500" rows="2" :aria-label="nt('繁体提示')" :disabled="locked"></textarea></label></div></details>
     <div class="qnw-two"><label class="qnw-label">{{nt('入口类型')}}<select :value="currentRow.kind" :aria-label="nt('入口类型')" :disabled="locked" @change="setKind($event.target.value)"><option v-for="(label,key) in kinds" :key="key" :value="key">{{nt(label)}}</option></select></label><label class="qnw-label">{{nt('父分组')}}<select v-model="drafts[selected].parentId" :aria-label="nt('父分组')" :disabled="locked"><option :value="null">{{nt('不放入分组')}}</option><option v-for="group in parents" :key="group.id" :value="group.id">{{menuLabel(group,currentLang)}}</option></select></label></div>
     <label v-if="currentRow.kind==='internal'" class="qnw-label">{{nt('选择站内页面')}}<select :value="currentRow.path" :aria-label="nt('选择站内页面')" :disabled="locked" @change="selectPath($event.target.value)"><option v-if="!catalog.routes.some(row=>row.path===currentRow.path)" :value="currentRow.path">{{currentRow.path||nt('请选择已提供的站内页面。')}}</option><option v-for="page in catalog.routes" :key="page.key" :value="page.path">{{menuLabel(page,currentLang)}}</option></select></label>
     <template v-if="['embed','external'].includes(currentRow.kind)"><label class="qnw-label">{{nt('画布或链接地址')}}<input v-model="drafts[selected].targetUrl" :aria-label="nt('画布或链接地址')" maxlength="2048" placeholder="https://" :disabled="locked"/></label><p v-if="currentRow.kind==='embed'" class="qnw-field-note">{{nt('仅在本人打开入口后载入画布。')}}</p></template>
     <div class="qnw-checks"><label><input v-model="drafts[selected].openInNewTab" type="checkbox" :disabled="locked"/>{{nt('在新标签页打开')}}</label><label><input v-model="drafts[selected].requireLogin" type="checkbox" :disabled="locked"/>{{nt('打开前需要登录')}}</label></div>
     <section class="qnw-icon-section"><div><h3>{{nt('图标与状态')}}</h3><div class="qnw-icon-tabs"><button v-for="[key,label] in [['symbol','图形图标'],['image','图片图标']]" :key="key" type="button" :class="{active:currentRow.iconMode===key}" :disabled="locked" @click="drafts[selected].iconMode=key">{{nt(label)}}</button></div></div><div v-if="currentRow.iconMode==='symbol'" class="qnw-two"><label class="qnw-label">{{nt('普通图标')}}<select v-model="drafts[selected].icon" :aria-label="nt('普通图标')" :disabled="locked"><option v-if="!catalog.icons.includes(currentRow.icon)" :value="currentRow.icon">{{currentRow.icon}}</option><option v-for="icon in catalog.icons" :key="icon" :value="icon">{{iconLabel(icon)}}</option></select></label><label class="qnw-label">{{nt('选中图标')}}<select v-model="drafts[selected].activeIcon" :aria-label="nt('选中图标')" :disabled="locked"><option value="">{{nt('沿用普通图标')}}</option><option v-if="currentRow.activeIcon&&!catalog.icons.includes(currentRow.activeIcon)" :value="currentRow.activeIcon">{{currentRow.activeIcon}}</option><option v-for="icon in catalog.icons" :key="icon" :value="icon">{{iconLabel(icon)}}</option></select></label></div>
      <div v-else class="qnw-image-icons"><div v-for="[field,label] in [['iconUrl','普通图标'],['activeIconUrl','选中图标']]" :key="field"><MenuIcon :row="{...currentRow,iconMode:'image',iconUrl:drafts[selected][field],activeIconUrl:''}"/><label class="qnw-upload">{{nt('上传图标图片')}}<input type="file" accept="image/png,image/jpeg,image/webp" :aria-label="nt('上传图标图片')+' · '+nt(label)" :disabled="locked||imageBusy" @change="uploadIcon($event,field)"/></label><label class="qnw-label">{{nt(field==='iconUrl'?'图标图片地址':'选中图片地址')}}<input v-model="drafts[selected][field]" :aria-label="nt(field==='iconUrl'?'图标图片地址':'选中图片地址')" :disabled="locked"/></label><button type="button" :disabled="locked||!drafts[selected][field]" @click="drafts[selected][field]=''">{{nt('移除图片')}}</button></div><p class="qnw-field-note">{{nt('图片会整理为 128 × 128 图标。')}}</p></div>
      <div class="qnw-icon-preview"><span><MenuIcon :row="currentRow"/>{{nt('普通图标')}}</span><span><MenuIcon :row="currentRow" active/>{{nt('选中图标')}}</span></div>
     </section>
     <div class="qnw-two"><label class="qnw-label">{{nt('展示区域')}}<select v-model="drafts[selected].surface" :aria-label="nt('展示区域')" :disabled="locked"><option value="client">{{nt('创作入口')}}</option><option value="manage">{{nt('管理入口')}}</option><option value="both">{{nt('创作与管理')}}</option></select></label><label class="qnw-label">{{nt('设备范围')}}<select v-model="drafts[selected].platform" :aria-label="nt('设备范围')" :disabled="locked"><option value="all">{{nt('所有设备')}}</option><option value="desktop">{{nt('电脑')}}</option><option value="mobile">{{nt('手机与窄屏')}}</option></select></label></div>
     <div class="qnw-two"><label class="qnw-label">{{nt('可见范围')}}<select v-model="drafts[selected].roles" :aria-label="nt('可见范围')" :disabled="locked"><option v-if="!['ALL','ADMIN','USER,ADMIN','ADMIN,USER'].includes(currentRow.roles)" :value="currentRow.roles">{{currentRow.roles||nt('所有访问者')}}</option><option value="ALL">{{nt('所有访问者')}}</option><option value="USER,ADMIN">{{nt('所有登录用户')}}</option><option value="ADMIN">{{nt('仅管理员')}}</option></select></label><label class="qnw-label">{{nt('排序')}}<input v-model.number="drafts[selected].sort" type="number" step="1" min="-1000000" max="1000000" :aria-label="nt('排序')" :disabled="locked"/></label></div><p class="qnw-field-note">{{nt('小的数字排在前面，也可以拖动同组入口。')}}</p>
     <p v-if="problems[selected]" class="qnw-inline-error" role="alert">{{nt(problems[selected])}}</p><div class="qnw-editor-footer"><button v-if="bases[selected]" type="button" class="qnw-button qnw-archive" :disabled="locked||!!changes.length" @click="organize(selected,'archive')"><ClientIcon name="folder"/>{{nt('收起到回收站')}}</button><button v-else type="button" class="qnw-button" :disabled="locked" @click="removeNew(selected)">{{nt('撤销新增')}}</button><span v-if="changes.length&&bases[selected]">{{nt('先保存或撤回本次编辑，再整理导航。')}}</span></div>
    </div>
   </section><section v-else class="qnw-editor qnw-no-selection"><ClientIcon name="layout"/><h2>{{nt('选择要调整的入口')}}</h2><p>{{nt('选择左侧入口，或添加一个新的位置。')}}</p></section>
  </div>
  <section class="qnw-preview"><header><div><p class="qnw-eyebrow">A LITTLE LOOK AHEAD</p><h2>{{nt('预览导航')}}</h2><p>{{nt('查看你的调整在不同空间里的样子。')}}</p></div><div class="qnw-preview-controls"><select v-model="previewSurface" :aria-label="nt('预览导航')+' · '+nt('展示区域')"><option value="client">{{nt('创作入口')}}</option><option value="manage">{{nt('管理入口')}}</option></select><select v-model="previewRole" :aria-label="nt('预览导航')+' · '+nt('可见范围')"><option value="ADMIN">{{nt('管理员视角')}}</option><option value="USER">{{nt('用户视角')}}</option><option value="GUEST">{{nt('访客视角')}}</option></select><select v-model="previewDevice" :aria-label="nt('预览导航')+' · '+nt('设备范围')"><option value="desktop">{{nt('电脑')}}</option><option value="mobile">{{nt('手机与窄屏')}}</option></select></div></header><div class="qnw-preview-stage" :class="{'is-phone':previewDevice==='mobile'}"><div><div class="qnw-preview-brand"><img src="/brand/qgauss-mark.svg" alt=""/><b>QGauss AI</b></div><NavigationTree :rows="previewRows" :interactive="false"/><p v-if="!previewRows.length">{{nt('当前范围没有可显示的入口。')}}</p></div><aside aria-hidden="true"><i></i><i></i><i></i><div><span></span><span></span><span></span></div></aside></div><p class="qnw-field-note">{{nt('这只是预览，不会打开链接或载入外部画布。')}}</p></section>
  <footer class="qnw-actions" :class="{'has-edits':changes.length}"><div><i :class="{changed:changes.length}"></i><span><b>{{nt(changes.length?'有 {count} 项改动等待保存':'还没有需要保存的改动。',{count:changes.length})}}</b><small>{{readAt?nt('最后读取')+' '+formatDate(readAt):nt('正在读取导航')}}</small></span></div><button type="button" class="qnw-button" :disabled="locked||!changes.length" @click="discard">{{nt('撤回本次编辑')}}</button><button ref="reviewButton" type="button" class="qnw-button qnw-primary" :disabled="locked||loading||!changes.length" @click="openReview">{{nt('预览这次调整')}}<ClientIcon name="arrow"/></button></footer>
 </div>
 <dialog ref="dialog" class="qnw-dialog" :aria-label="nt(review?.action==='discard'?'确认撤回本次编辑':closing?'结束这次等待':'核对本次调整')" @cancel.prevent="cancelDialog"><template v-if="review||closing"><header><div><p class="qnw-eyebrow">QGAUSS / ONE CLEAR DECISION</p><h2>{{nt(review?.action==='discard'?'确认撤回本次编辑':closing?'结束这次等待':'核对本次调整')}}</h2></div><button type="button" class="qnw-icon-button" :disabled="busy" :aria-label="nt('关闭预览')" @click="cancelDialog"><ClientIcon name="close"/></button></header><p>{{nt(closing?'只结束尚未保存的申请；已经保存的导航会保留。':review?.action==='discard'?'尚未保存的调整会从当前草稿移除。':review?.action==='save'?'只保存这次确认的变化，其他入口保持现状。':'分组中的相关入口已一并列出。')}}</p><p v-if="review&&!['save','discard'].includes(review.action)">{{nt('本次会整理 {count} 个分组或入口。',{count:review.rows.length})}}</p><div v-if="review?.rows.length" class="qnw-review-list"><article v-for="row in review.rows" :key="row.id"><h3>{{row.title||nt('待添加')}}<span v-if="!row.before">{{nt('本次新增')}}</span></h3><template v-if="review.action==='save'"><dl v-for="field in row.fields" :key="field"><dt>{{nt(MENU_FIELD_LABELS[field])}}</dt><dd><small>{{nt('修改前')}}</small><p>{{formatValue(field,row.before?.[field])}}</p></dd><ClientIcon name="arrow"/><dd><small>{{nt('修改后')}}</small><p>{{formatValue(field,row.after[field])}}</p></dd></dl></template><p v-else>{{nt(review.action==='archive'?'已收起':'恢复使用')}}</p></article></div><p v-if="error" class="qnw-inline-error" role="alert">{{nt(error)}}</p><footer><button type="button" class="qnw-button" :disabled="busy" @click="cancelDialog">{{nt(closing?'继续核对':review?.action==='discard'?'保留编辑':'返回调整')}}</button><button type="button" class="qnw-button qnw-primary" :disabled="busy" @click="closing?conclude():confirm()"><ClientIcon :name="busy?'refresh':'check'"/>{{nt(saving?'正在保存':closing?'确认结束':review?.action==='discard'?'确认撤回':review?.action==='archive'?'确认收起':review?.action==='restore'?'确认恢复':'确认保存')}}</button></footer></template></dialog>
 </div>
</template>
<script setup>
import{computed,nextTick,onBeforeUnmount,ref,watch}from'vue';
import{currentLang}from'../../i18n/index.js';
import{MENU_FIELD_LABELS,navigationText}from'../../i18n/navigation-messages.js';
import{NAVIGATION_CATALOG,menuLabel,menuProblem}from'../../lib/navigation.js';
import{useMenuWorkspace}from'../../composables/useMenuWorkspace.js';
import ClientIcon from'../reference/ClientIcon.vue';import BrandLoader from'../design/BrandLoader.vue';import MenuIcon from'./MenuIcon.vue';import NavigationTree from'./NavigationTree.vue';import'./navigation-workspace.css';
const state=useMenuWorkspace(),{items,drafts,bases,conflicts,selected,scope,query,loading,saving,busy,locked,error,loadError,notice,receipt,pending,review,closing,readAt,rows,changes,active,groups,problems,currentRow,outline,dirty,choose,refresh,resolve,add,removeNew,setKind,useDefaultName,selectPath,move,openReview,organize,discard,confirm,checkPending,conclude}=state;
let alive=true;
const catalog=NAVIGATION_CATALOG,nt=(value,params)=>navigationText(currentLang.value,value,params),scopes=[['client','创作入口'],['manage','管理入口'],['trash','回收站']],kinds={group:'导航分组',internal:'站内页面',embed:'嵌入画布',external:'外部链接'},dragged=ref(''),imageBusy=ref(false),dialog=ref(null),reviewButton=ref(null),previewSurface=ref('client'),previewRole=ref('ADMIN'),previewDevice=ref('desktop');
const parents=computed(()=>groups.value.filter(row=>row.id!==selected.value&&!isDescendant(row.id,selected.value)));
function isDescendant(id,parent){const map=new Map(rows.value.map(row=>[row.id,row])),seen=new Set();let current=map.get(id)?.parentId;while(current&&!seen.has(current)){if(current===parent)return true;seen.add(current);current=map.get(current)?.parentId;}return false;}
function selectScope(key){scope.value=key;query.value='';selected.value=outline.value[0]?.id||'';}
function countScope(key){return rows.value.filter(row=>key==='trash'?!!row.deletedAt:!row.deletedAt&&(row.surface===key||row.surface==='both')).length;}
function drop(id){if(dragged.value)move(dragged.value,0,id);dragged.value='';}
function formatDate(value){return new Date(value).toLocaleString(currentLang.value==='en'?'en-US':currentLang.value==='zh-TW'?'zh-TW':'zh-CN',{hour12:false});}
const iconNames={chat:'对话体验',apps:'应用与成长',agent:'行动搭档',image:'图像创作',palette:'图标与状态',gallery:'创意广场',mindmap:'思维导图',microphone:'声音工作室',video:'视频创作',model:'模型广场',wallet:'会员与计费',user:'个人空间',settings:'系统配置',layout:'导航工作台',globe:'服务连接',chart:'统计',mail:'邮箱发件',star:'预设',lock:'账号与安全',check:'确认保存',folder:'导航分组',file:'文件与上传',link:'外部链接',bolt:'快捷入口'};
function iconLabel(icon){const page=catalog.routes.find(row=>row.icon===icon);return page?menuLabel(page,currentLang.value):nt(iconNames[icon]||icon);}
function formatValue(field,value){if(value===undefined||value===null||value==='')return nt('未填写');if(typeof value==='boolean')return nt(value?'开启':'关闭');if(field==='iconUrl'||field==='activeIconUrl')return nt('已选择图标图片');if(field==='parentId')return menuLabel(rows.value.find(row=>row.id===value)||{title:value},currentLang.value);if(field==='kind')return nt(kinds[value]);if(field==='surface')return nt({client:'创作入口',manage:'管理入口',both:'创作与管理'}[value]);if(field==='platform')return nt({all:'所有设备',desktop:'电脑',mobile:'手机与窄屏'}[value]);if(field==='roles')return nt(value==='ADMIN'?'仅管理员':value==='ALL'?'所有访问者':'所有登录用户');if(field==='icon'||field==='activeIcon')return iconLabel(value);if(field==='standardKey')return nt(value?'开启':'关闭');return String(value);}
const previewRows=computed(()=>{
 const valid=active.value.filter(row=>(row.surface===previewSurface.value||row.surface==='both')&&(row.platform==='all'||row.platform===previewDevice.value)),children=new Map(),role=previewRole.value;
 for(const row of valid){const key=row.parentId||'';if(!children.has(key))children.set(key,[]);children.get(key).push(row);}
 function visit(parent,seen,depth){if(depth>6)return[];return(children.get(parent)||[]).sort((a,b)=>a.sort-b.sort||a.id.localeCompare(b.id)).flatMap(row=>{const roles=row.roles.trim()?row.roles.split(',').map(value=>value.trim()):['ALL'],allowed=roles.includes('ALL')||roles.includes(role==='GUEST'?'USER':role);if(seen.has(row.id)||!row.visible||!allowed)return[];const route=catalog.routes.find(page=>page.path===row.path);if(row.kind==='internal'&&route?.admin&&role!=='ADMIN')return[];return[{...row,titleEn:menuLabel(row,'en'),titleTw:menuLabel(row,'zh-TW'),path:row.kind==='internal'?row.path:'/navigation/entry/'+row.id,available:!menuProblem(row,['path','kind','targetUrl'],false),loginRequired:role==='GUEST'&&row.requireLogin,url:row.kind==='external'?row.targetUrl:null,children:visit(row.id,new Set([...seen,row.id]),depth+1)}];});}return visit('',new Set(),0);
});
async function uploadIcon(event,field){const file=event.target.files?.[0],id=selected.value,identity=state.auth.identityRevision;event.target.value='';if(!file||locked.value)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024){error.value='请使用较小的 PNG、JPEG 或 WebP 图片。';return;}imageBusy.value=true;const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();if(!image.naturalWidth||image.naturalWidth*image.naturalHeight>20000000)throw Error();const canvas=document.createElement('canvas');canvas.width=128;canvas.height=128;const context=canvas.getContext('2d'),scale=Math.min(128/image.naturalWidth,128/image.naturalHeight),width=image.naturalWidth*scale,height=image.naturalHeight*scale;context.drawImage(image,(128-width)/2,(128-height)/2,width,height);const value=canvas.toDataURL('image/png');if(value.length>98304)throw Error();if(alive&&identity===state.auth.identityRevision&&drafts[id]&&!locked.value)drafts[id][field]=value;}catch{if(alive&&identity===state.auth.identityRevision)error.value='暂时无法读取这张图片。';}finally{URL.revokeObjectURL(url);if(alive)imageBusy.value=false;}}
function cancelDialog(){if(busy.value)return;review.value=null;closing.value=false;}
watch(()=>!!review.value||closing.value,async open=>{await nextTick();if(!dialog.value)return;if(open&&!dialog.value.open)dialog.value.showModal();else if(!open&&dialog.value.open){dialog.value.close();reviewButton.value?.focus();}});
onBeforeUnmount(()=>{alive=false;if(dialog.value?.open)dialog.value.close();});
</script>
